def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            not seen[ny][nx] and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        stack.append((ny, nx))

            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)
            height, width = maxr - minr + 1, maxc - minc + 1
            local = {(y - minr, x - minc) for y, x in cells}
            frame = (
                height >= 3 and width >= 3 and
                all((0, x) in local and (height - 1, x) in local for x in range(width)) and
                all((y, 0) in local and (y, width - 1) in local for y in range(height))
            )
            objects.append({
                "cells": local, "color": color, "r": minr, "c": minc,
                "height": height, "frame": frame
            })

    placed = []
    # Frames move up, with other frames as obstacles.
    for obj in sorted((o for o in objects if o["frame"]), key=lambda o: o["r"]):
        r = obj["r"]
        while r > 0:
            candidate = {(r - 1 + y, obj["c"] + x) for y, x in obj["cells"]}
            if any((y, x) in occupied for other in placed
                   for occupied in [other["abs_cells"]] for y, x in candidate):
                break
            r -= 1
        obj["abs_cells"] = {(r + y, obj["c"] + x) for y, x in obj["cells"]}
        placed.append(obj)

    # Non-frames move down, with other non-frames as obstacles.
    fallen = []
    nonframes = [o for o in objects if not o["frame"]]
    for obj in sorted(nonframes, key=lambda o: o["r"], reverse=True):
        r = obj["r"]
        while r + obj["height"] < h:
            candidate = {(r + 1 + y, obj["c"] + x) for y, x in obj["cells"]}
            if any(candidate & other["abs_cells"] for other in fallen):
                break
            r += 1
        obj["abs_cells"] = {(r + y, obj["c"] + x) for y, x in obj["cells"]}
        fallen.append(obj)

    out = [[0] * w for _ in range(h)]
    for obj in objects:
        for r, c in obj["abs_cells"]:
            out[r][c] = obj["color"]
    return out

def transform(grid):
    from itertools import permutations

    h, w = len(grid), len(grid[0])
    frames = []

    # Find rectangular frames: their bounding-box perimeter is entirely
    # the frame color, with no additional cells of that color inside.
    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        perimeter = {
            (r, c)
            for r in range(r0, r1 + 1)
            for c in range(c0, c1 + 1)
            if r in (r0, r1) or c in (c0, c1)
        }
        if set(cells) == perimeter:
            frames.append((color, r0, r1, c0, c1))

    frame_colors = {f[0] for f in frames}
    marker_colors = [color for color in range(1, 10)
                     if color not in frame_colors
                     and any(grid[r][c] == color
                             for r in range(h) for c in range(w))]
    counts = {
        color: sum(grid[r][c] == color for r in range(h) for c in range(w))
        for color in marker_colors
    }

    # Match each frame to the marker color whose count best matches the
    # number of cells in its checkerboard fill.
    best_assignment = ()
    best_score = None
    if len(marker_colors) >= len(frames):
        for assignment in permutations(marker_colors, len(frames)):
            score = 0
            for frame, color in zip(frames, assignment):
                _, r0, r1, c0, c1 = frame
                score += abs(
                    counts[color] -
                    sum(1 for r in range(r0 + 1, r1)
                        for c in range(c0 + 1, c1)
                        if (r + c) % 2 == 0)
                )
            if best_score is None or score < best_score:
                best_score = score
                best_assignment = assignment

    out = [[0] * w for _ in range(h)]
    for i, (frame_color, r0, r1, c0, c1) in enumerate(frames):
        fill_color = best_assignment[i] if best_assignment else 0
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if r in (r0, r1) or c in (c0, c1):
                    out[r][c] = frame_color
                elif (r + c) % 2 == 0:
                    out[r][c] = fill_color
    return out
